            "b": "層 | 位階 | 內容\n1 | <b>法律</b> | 資通安全管理法（母法，最高位階）\n2 | <b>命令</b> | 資安法相關 <b>8 項子法</b>（法規命令）\n3 | <b>行政規則</b> | 機關內部控制及資安相關規定\n4 | <b>行政指導文件</b> | 各式資安參考指引（<b>不具強制法效力</b>，但有高度技術與作業參考價值）\n<b>8 部子法（要能默寫）</b>：\n① 資通安全管理法施行細則\n② 資通安全責任等級分級辦法\n③ 資通安全事件通報應變及演練辦法\n④ 資通安全維護計畫實施情形稽核辦法\n⑤ 資通安全情資分享辦法\n⑥ 公務機關所屬人員辦理資通安全事項作業辦法\n⑦ 危害國家資通安全產品審查辦法\n⑧ 國家資通安全會報設置辦法\n<span class=\"hl-r\">陷阱：參考指引屬第四層行政指導文件，不具強制力，常被說成「與子法同位階」。</span>"
