            "b": "<span class=\"hl-r\">本張頁首誤植為「2-2」，實際仍屬 2-1 節。</span>\n<b>立法目的（逐字背）</b>：為積極推動國家資通安全政策，加速建構國家資通安全環境，以保障國家安全，維護社會公共利益。\n<b>主管機關</b>：數位發展部；<b>資安專責機關</b>：數位發展部<b>資通安全署</b>。\n適用對象二分：\n類別 | 定義與實例\n<b>公務機關</b> | 指依法行使公權力之中央、地方機關（構）或公法人；<b>但不包含軍事機關及情報機關</b>\n<b>特定非公務機關</b> | ① 關鍵基礎設施提供者（例：中油）② 公營事業（例：台糖）③ 特定財團法人（例：工研院）④ <span class=\"hl-g\">受政府控制之事業、團體或機構（114/9/24 新增之第四類）</span>\n<span class=\"hl-r\">陷阱：軍事機關與情報機關「不屬於」本法所稱公務機關，這是最常考的排除項。</span>"
