            "h": "⭐⭐ 簡報 1-32｜會報設置辦法：法源、理念、成員與六項任務",
            "b": "<b>法源與定位</b>：為協調各政府機關、中央及地方間資安事務，健全整體資安管理、強化橫向溝通聯繫，將現行國家資通安全會報入法明文化——原「行政院國家資通安全會報設置要點」由<b>行政規則提升至法規命令</b>。\n<b>理念</b>：資安法納管全國公務機關，推動面向廣泛，「<b>聯防</b>」已是國際趨勢，需跨院、跨部會機關、跨領域及公私協力合作。\n<b>會報成員（跨五院）</b>：總統府、行政院、立法院、司法院、考試院、監察院、國家安全局、所屬中央二級機關、各直轄市政府。\n<b>會報六項任務</b>（動詞是關鍵）：\n① 國家資通安全政策之<b>協調及推動</b>\n② 國家資通安全應變機制之<b>協調及溝通</b>\n③ 國家資通安全重大計畫之<b>諮詢及審議</b>\n④ 跨機關資通安全事務之<b>協調及推動</b>\n⑤ 資通安全工作辦理情形之<b>督導及評核</b>\n⑥ 其他有關國家資通安全業務之督導、協調及推動\n<span class=\"hl-g\">加值：成員新增總統府與五院代表，是本辦法「入法」後最大的變化，用以達成跨院聯防。</span>"
