            "b": "<b>前提</b>：受託業務<b>涉及國家機密</b>者，執行受託業務之相關人員應接受適任性查核，並依<b>國家機密保護法</b>之規定<b>管制其出境</b>。\n查核事由五款：\n① 曾犯刑法<b>妨害電腦使用罪章</b>之罪，經有罪判決確定，或通緝有案尚未結案\n② 曾犯<b>洩密罪</b>，或於動員戡亂時期終止後犯<b>內亂罪、外患罪</b>，經判刑確定，或通緝有案尚未結案\n③ 曾任公務員，因違反相關安全保密規定受<b>懲戒或記過以上</b>行政懲處\n④ 曾受到外國政府、大陸地區、香港或澳門政府之<b>利誘、脅迫</b>，從事不利國家安全或重大利益情事\n⑤ 其他與國家機密保護相關之具體項目\n<b>程序要件（必考）</b>：辦理適任性查核前，<b>應經當事人書面同意</b>。\n<span class=\"hl-r\">陷阱：查核前提是「涉及國家機密」，並非所有委外案都要查核。</span>"
