            "b": "條 | 內容\n§1 | 依據\n§2 | 維護計畫辦理與情形提出\n§3 | 系統平臺提出實施情形\n§4 | <b>收受實施情形之公務機關訂定稽核計畫</b>\n§5 | 主管機關得稽核各機關維護計畫實施情形\n§6 | <b>受稽核機關遴選與計畫內容</b>\n§7 | 稽核通知與日期調整\n§8 | 稽核執行與配合義務\n§9 | 稽核小組之組成與<b>迴避</b>\n§10 | 稽核結果報告之交付\n§11 | <b>改善報告與追蹤</b>\n§12 | 主管機關稽核之協助\n§13 | 稽核作業得委任\n§14 | 自發布日施行\n流程圖順序：<b>系統平臺提出實施情形 → 擬定稽核計畫 → 成立稽核小組 → 通知受稽機關 → 進行稽核及其結果 → 改善報告及追蹤</b>。"
