            "b": "項目 | 內容\n<b>法律授權</b> | 資通安全管理法 <b>§11</b>；危害國家資通安全產品審查辦法 <b>114.12.01 施行</b>\n<b>限制使用</b> | 公務機關<b>不得下載、安裝或使用</b>危害國家資通安全產品（包含<b>大陸地區、香港或澳門廠牌</b>資通訊產品）。定義：經主管機關認定，對國家資通安全具有<b>直接或間接</b>造成危害風險，影響<b>政府運作或社會安定</b>之資通系統、服務或產品\n<b>審查程序</b> | 提報機關提供情資與佐證資料 → <b>形式審查</b> →（<b>快速評估</b>／<b>逕為結案</b>）→ <b>產品風險評估</b> → 經評估屬<b>高風險產品</b> → 經認定屬<b>危害產品</b> → 情資分享\n<b>風險評估依據</b> | <b>硬體物料清單</b>（是否具計算能力、是否屬陸資／陸製零組件）與<b>軟體產品元件表</b>\n<b>審查成員</b> | 召集人＝<b>數發部部長或其授權之人</b>；當然成員＝<b>國安會、國安局、法務部、經濟部、內政部、陸委會、數發部</b>\n<b>情資分享對象</b> | <b>公務機關、關鍵基礎設施提供者、N-ISAC 會員</b>三類\n<span class=\"hl-r\">陷阱：情資分享對象是三類，「特定非公務機關」全體並不在列，只有關鍵基礎設施提供者與 N-ISAC 會員。</span>"
