            "h": "⭐ 簡報 1-51｜危害產品的提報機關與提報表效益",
            "b": "<b>提報義務</b>：公務機關及特定非公務機關對於資通系統、服務或產品，認有危害國家資通安全之疑慮時，應依規定<b>填具提報表並檢附相關文件</b>送交主管機關審查。\n<b>公務機關由各該機關提報，四類</b>：\n一 | 總統府、國家安全會議、五院及其直屬機關\n二 | 中央二級機關所屬或所監督之公務機關\n三 | 直轄市政府、直轄市議會、縣（市）政府及縣（市）議會\n四 | 直轄市、縣（市）政府所屬、所監督之公務機關，與所轄鄉（鎮、市）公所、直轄市山地原住民區公所、鄉（鎮、市）民代表會及直轄市山地原住民區民代表會及其所屬或所監督之公務機關\n<b>特定非公務機關</b>：由其<b>中央目的事業主管機關</b>提報。\n<b>提報表兩項效益</b>：① 機關了解風險來源，提升機關<b>識別風險</b>能力 ② 同一部會各機關使用產品通常來源相同，使上級機關<b>提前掌握</b>所屬各機關之潛在風險，提高機關<b>縱向資安聯防</b>效率。"
