            "b": "<b>沿革</b>：<b>92/2/6 公布、92/10/1 施行、112/12/27 修正</b>。\n<b>定義（兩個要件）</b>：① 為確保國家安全或利益而<b>有保密之必要</b> ② 對政府機關<b>持有或保管</b>之資訊，<b>經依本法核定機密等級</b>者。\n<b>範圍七款</b>：\n① <b>軍事計畫、武器系統或軍事行動</b>\n② <b>外國政府</b>之國防、政治或經濟資訊\n③ <b>情報組織</b>與其活動\n④ 政府<b>通信、資訊之保密技術、設備或設施</b>\n⑤ <b>外交或大陸事務</b>\n⑥ <b>科技或經濟事務</b>\n⑦ 其他為確保國家安全或利益而有保密之必要者\n<span class=\"hl-r\">陷阱：公布 92/2/6 與施行 92/10/1 不同日；修正日 112/12/27 常被誤記為 110 年。</span>"
