            "b": "<span class=\"hl-g\">本法為簡報獨有之新增法規。公布與施行<b>同一天</b>（115/1/14）。</span>\n<b>主管機關（§2）</b>：中央為<b>國家科學及技術委員會</b>；地方為直轄市、縣（市）政府。\n<b>AI 定義（§3）</b>：指具<b>自主運行能力</b>之系統，透過<b>機器學習及演算法</b>，能產出<b>預測、內容、建議或決策</b>。\n<b>七大原則（§4）</b>：\n① <b>永續發展</b>（環境與福祉）\n② <b>人類自主</b>（尊重人權、可監督）\n③ <b>隱私治理</b>（資料最小化）\n④ <b>資安防護</b>（系統穩健性）\n⑤ <b>透明可釋</b>（產出標記、風險揭露）\n⑥ <b>公平不歧視</b>（避免演算法偏差）\n⑦ <b>問責機制</b>（內部治理與外部責任）\n<b>推動機制與激勵（§6～§12）之前半</b>：組織戰略（§6）成立「<b>國家人工智慧戰略特別委員會</b>」，由<b>行政院長</b>召集，訂定國家發展綱領；教育與人才（§7～§8）推動學校及公務體系之 AI 倫理教育、促進產官學跨域人才交流。\n<span class=\"hl-r\">陷阱：主管機關是「國科會」不是數位發展部——但風險分類框架由數位發展部推動（見下一張）。</span>"
