            "b": "<b>風險接受準則（Risk Acceptance Criteria）：先決定風險處理範圍。</b>\n機關會因<b>所負責任務的類別與性質、服務對象、內部資源及經費預算</b>等因素，影響風險處理範圍。\n在<b>有限資源</b>下，決定哪些風險<b>影響層面較大、需優先處理</b>，哪些風險<b>影響層面較小</b>，在資源不足情況下<b>暫時予以接受而保留風險</b>。\n<span class=\"hl-r\">觀念陷阱：風險接受準則是在「處理之前」就先訂好的門檻，不是處理完才回頭補訂。</span>"
