            "b": "<b>風險避免</b>：<b>避免可能造成特定風險增加的活動或情況</b>。\n簡報兩個範例：\n範例 | 情境 | 做法\n<b>範例 1</b> | 第三方開源函式庫可能挾帶漏洞 | <b>管制使用任何第三方未經嚴格安全審核的開源函式庫</b>\n<b>範例 2</b> | 發電機放置地下室、颱風淹水 | <b>將發電機移置樓上</b>\n<span class=\"hl-g\"><b>金句必背</b>：辦理社交工程演練，除了需進行演練作業外，<b>強化認知訓練與宣導，才是防範社交工程攻擊或進階持續性威脅（APT）攻擊最經濟有效的控制措施</b>。</span>\n<span class=\"hl-r\">陷阱：問「最經濟有效」時，答案不是採購設備、不是加做滲透測試，而是認知訓練與宣導。</span>"
