            "b": "<b>風險處理計畫</b>宜描述將如何處理評定之風險，以<b>滿足風險接受準則</b>。\n於某些情況中，<b>殘餘風險之等級可能不符合風險接受準則</b>，因為該準則<b>於適用時未考量當時之環境</b>。\n兩種仍須接受的理由：① <b>伴隨風險之利益非常有吸引力</b> ② <b>風險修改之成本太高</b>。\n<span class=\"hl-g\">此種環境指出<b>風險接受準則不恰當，若可能宜加以修訂</b>，是「改準則」而不是硬套。</span>\n決策者可能必須接受<b>不符合常態風險接受準則</b>之風險（normal risk acceptance criteria）。若此為必要，決策者宜<b>明確地在該風險上註解</b>，並包含<b>無視常態風險接受準則之決策的衡量理由</b>。\n<span class=\"hl-r\">陷阱：正解是「註解理由＋必要時修訂準則」，不是「一律不得接受」或「口頭同意即可」。</span>"
