            "b": "<b>資通安全框架：NIST CSF 2.0 : 2024</b>。本張同時呈現文件章節與<b>六大功能輪圖</b>。\n文件結構：1. 資通安全框架（CSF）概述　2. CSF 核心介紹　3. CSF 概況及層級介紹（3.1 CSF <b>剖繪</b>、3.2 CSF <b>層級</b>）　4. 補充 CSF 的線上資源介紹　5. 加強網路安全風險溝通與整合（5.1 改善風險管理溝通、5.2 改善與其他風險管理計畫的整合）。\n附錄：<b>附錄 A：CSF 核心</b>、<b>附錄 B：CSF 層級</b>、<b>附錄 C：詞彙表</b>。\n輪圖擺法：<b>治理（GV）在正中央</b>，識別、保護、偵測、回應、復原五個功能環繞四周，象徵治理貫穿其他五項。"
