            "b": "NIST 網路安全框架（Cybersecurity Framework, CSF）是一個<b>自願性</b>的框架，旨在幫助組織更好地<b>管理及降低網路安全風險</b>。\n版本沿革：<b>CSF 1.0 發布於 2014 年，主要關注「保護」</b>；經多年實踐及回饋，<b>NIST 於 2024 年發布 CSF 2.0</b>，進行重要的更新及擴展。\n功能 | 縮寫 | 內容\n<b>治理</b> | <b>GV</b> | 建立並溝通網路安全<b>策略、角色、責任及監督</b>（<span class=\"hl-g\">2.0 新增</span>）\n<b>識別</b> | <b>ID</b> | 了解組織的網路安全風險，包括<b>資產、業務環境、治理結構、風險評估及供應鏈</b>\n<b>保護</b> | <b>PR</b> | 制定並實施保障措施，以支持<b>限制或遏制</b>網路安全事件的能力\n<b>偵測</b> | <b>DE</b> | 制定並實施活動，以<b>識別網路安全事件的發生</b>\n<b>回應</b> | <b>RS</b> | 制定並實施有關網路安全事件的<b>行動</b>\n<b>復原</b> | <b>RC</b> | 制定並實施計劃，以便在網路安全事件後<b>恢復能力及服務</b>\n<span class=\"hl-r\">陷阱：六大功能不含「預防」「稽核」；縮寫易混的是 DE（偵測）與 RS（回應）／RC（復原）。</span>"
