            "b": "<b>定位</b>：提供組織<b>建立、實施、維護及持續改進</b>資訊安全風險管理流程的<b>指導方針</b>。其核心目標是幫助組織有效地<b>識別、分析、評估及處理</b>資訊安全風險，以<b>保護其資訊資產</b>。\n主要重點 | 內容\n<b>風險管理框架</b> | 強調建立一個<b>結構化</b>的風險管理框架，該框架應<b>融入組織的整體資訊安全管理系統（ISMS）</b>\n<b>背景理解</b> | 強調在進行風險評估<b>之前</b>，需要充分理解組織的<b>內外部環境</b>、<b>利害關係者的需求及期望</b>，以及<b>確定風險管理的範圍</b>\n「背景理解」正是 3-2「<b>全景建立</b>」在國際標準中的對應段落。"
