            "b": "資通安全責任等級 | 專職人員配置人數（公務機關與特定非公務機關<b>相同</b>）\n<b>A 級</b> | 配置 <b>4 人</b>以上\n<b>B 級</b> | 配置 <b>2 人</b>以上\n<b>C 級</b> | 配置 <b>1 人</b>以上\n<b>D 級、E 級</b> | <b>無要求</b>\n<b>定義（逐字背）</b>：<b>資通安全專職人員</b>指應<b>全職執行資通安全業務</b>者，亦即<b>資通安全為其主要核心業務，且應優先辦理</b>。\n<b>資通安全專職人員以外之資訊人員</b>：指<b>其他實際從事資通安全業務或資訊業務</b>之人員。\n<b>辦理期限</b>：配置專職人員應於<b>初次受核定或等級變更後之 1 年內</b>完成；<b>人員異動時，亦同</b>。\n速記口訣：<b>4-2-1</b>（A、B、C），D、E 無要求。\n<span class=\"hl-r\">陷阱：「兼辦資安業務」不算專職；期限是 1 年內，且人員異動時要在 1 年內補齊。</span>"
