            "h": "⭐⭐ 簡報 1-115｜演練實務（二）：時間要求與 MTPD = RTO + WRT",
            "b": "<b>指標訂定要求</b>：是否至少針對<b>核心業務</b>訂定<b>最大可容忍中斷時間（MTPD）</b>，並至少針對<b>防護需求為「中」等級以上</b>之資通系統，訂定<b>從中斷後至重新恢復服務之可容忍時間要求（RTO）</b>及<b>可容忍資料損失之時間要求（RPO）</b>？是否<b>依 RPO 訂定資料及系統之備份頻率</b>？\n<b>演練時間要求（四條數學關係，必考）</b>：\n關係 | 內容\n① | <b>核心資通系統之 RTO 不宜大於非核心資通系統之 RTO</b>\n② | <b>MTPD ＝ RTO ＋ WRT</b>（WRT＝<b>工作恢復時間</b>）\n③ | <b>RTO 不可大於 MTPD</b>\n④ | <b>備份週期不可大於 RPO</b>\n<span class=\"hl-r\">陷阱：RTO／RPO 的訂定門檻是「<b>中等級以上</b>」而非「全部系統」；MTPD 除了 RTO 還要加上 WRT，只寫 MTPD＝RTO 是錯的。</span>"
