            "b": "雜湊是一種從任何資料中建立「<b>數位指紋</b>」的方法。三個性質：\n① 若依據<b>同一個雜湊函式</b>（例如 <b>SHA-256</b>）計算得到<b>兩個不相同的雜湊值</b>，則這兩個<b>原始輸入也是不相同</b>的。\n② 雜湊常用來<b>驗證資料完整性</b>。\n③ 雜湊因具有<b>單向性</b>，<b>無法從雜湊值計算回推原始訊息</b>，故也可用來<b>儲存使用者密碼</b>。\n<span class=\"hl-r\">陷阱：雜湊<b>不是加密</b>（不可逆、沒有金鑰、無法解回原文）；它提供的是<b>完整性</b>，不是機密性。</span>"
