            "b": "<b>目的</b>：確保<b>只有經過授權的使用者</b>才能存取系統，保障資通系統的安全。\n控制措施 | 普 | 中 | 高\n<b>使用者之識別與鑑別</b> | 資通系統應<b>識別及鑑別使用者</b>，並<b>禁止使用者使用共用帳號</b> | 同「普」 | ① 對資通系統之存取採取<b>多因子鑑別技術</b> ② 等級「中」及「普」之所有控制措施\n<b>身分驗證管理</b> | ① 使用<b>預設密碼初次登入</b>系統時，應於<b>登入後立即變更</b> ② 身分驗證相關資訊<b>不以明文傳輸</b> ③ 具備<b>帳戶鎖定機制</b>，帳號登入進行身分驗證<b>失敗達 5 次</b>後，<b>至少 15 分鐘</b>內不允許該帳號繼續嘗試登入 ④ 使用密碼驗證時應<b>強制最低密碼複雜度</b>，依機關密碼效期規定變更密碼 ⑤ 密碼變更時<b>至少不可以與前 3 次使用過之密碼相同</b> ⑥ 第 4、5 點措施對<b>外部使用者，機關得自行規範辦理</b> | ① <b>身分驗證機制應防範自動化程式</b>之登入或密碼更換嘗試 ② <b>密碼重設機制</b>對使用者<b>重新身分確認後，發送一次性及具有時效性符記</b> ③ 等級「普」之所有控制措施 | 同「中」（含普之全部）\n<span class=\"hl-r\">三個必背數字：<b>失敗 5 次、鎖定至少 15 分鐘、不得與前 3 次密碼相同</b>；<b>多因子鑑別只有「高」級要求</b>。</span>"
