            "b": "<b>目前使用「最廣泛」也「最簡便」的身分鑑別技術，亦是最不安全的身分鑑別技術。</b>\n<b>不安全的五個使用者行為</b>：\n① 使用者選用了「<b>懶人通行碼</b>」\n② <b>共用通行碼</b>\n③ 將<b>通行碼貼在螢幕上</b>\n④ <b>從不更改通行碼</b>\n⑤ 輸入通行碼時<b>被別人看到按下的通行碼</b>\n<b>針對通行碼的三種攻擊</b>：<b>字典猜測法、暴力式通行碼猜測、通行碼監聽</b>。\n<span class=\"hl-r\">口訣：<b>最廣泛、最簡便、最不安全</b>——三個形容詞同時出現在同一張投影片，是反向題的素材庫。</span>"
