            "b": "<b>安全系統發展生命週期（SSDLC）</b>強調於<b>專案各階段及早加入安全思維</b>，以打造<b>具備安全體質</b>的資通系統。\n階段 | 該階段的安全活動\n<b>需求階段</b> | <b>發展安全需求</b>\n<b>設計階段</b> | <b>識別威脅與分析風險</b>\n<b>開發階段</b> | <b>實作安全控制措施並避免常見弱點</b>、<b>源碼掃描</b>\n<b>測試階段</b> | <b>弱點掃描或滲透測試</b>、<b>驗證安全需求實作有效性</b>\n<b>部署與維運階段</b> | <b>組態強化</b>、<b>元件修補更新</b>、<b>系統源碼備份</b>\n<span class=\"hl-r\">最愛考的對應：<b>源碼掃描在「開發」階段</b>（不是測試）、<b>弱點掃描與滲透測試在「測試」階段</b>、<b>組態強化在「部署與維運」階段</b>。</span>"
