            "b": "控制措施 | 適用等級 | 內容\n<b>於伺服器端檢查</b> | 高中普 | <b>使用者輸入資料合法性檢查應置放於應用系統伺服器端</b>；<b>不可依賴客戶端檢查（如 JavaScript）</b>，以避免<b>被惡意繞過</b>\n<b>使用完整性驗證工具</b> | <b>高中</b> | 使用完整性驗證工具偵測<b>未授權變更特定軟體及資訊</b>；這些工具通常會<b>計算檔案或資料的雜湊值</b>，與<b>已知的安全基準</b>比較；發現違反完整性時應實施<b>機關指定之安全保護措施</b>（如<b>即時通報與告警、自動阻斷與隔離、保全日誌與復原</b>）\n<b>定期檢查完整性</b> | <b>高</b> | 應<b>定期執行軟體與資訊完整性檢查</b>；<b>定期比對上線正式版本與版本控制系統之版本內容差異</b>，以發現潛藏之資安事件\n<span class=\"hl-r\">全書最高頻的一句：<b>輸入合法性檢查必須在伺服器端</b>（前端 JavaScript 檢查可被繞過）。</span>"
