            "b": "面向 | 內容\n<b>政策</b> | 應建立可攜式設備的<b>使用限制與範圍</b>\n<b>存取控制</b> | ① 可攜式設備對機關資通系統的存取，應<b>符合機關使用限制與範圍</b> ② <b>關閉或避免觸發自動執行可攜式媒體中的程式</b>，以避免<b>病毒的傳染</b>\n<b>稽核</b> | <b>監視可攜式設備對資通系統的非授權存取</b>\n<span class=\"hl-r\">實作重點：<b>關閉自動執行（AutoRun）</b>是 USB 防毒最基本也最常考的措施。</span>"
