            "b": "安裝或啟用<b>可攜式媒體控管程式</b>，可對各種可攜式媒體與設備的存取行為做三件事：<b>「管制」、「偵測」及「記錄」</b>。\n涵蓋的設備類型（簡報列舉）：<b>CD-R/DVD-R、MemoryCard、USB、Firewire、Printer、iPhone、Palm、Windows Mobile、irDA、WiFi、Bluetooth</b>。\n<span class=\"hl-r\">三個動詞要記全：<b>管制、偵測、記錄</b>——只寫「禁止使用 USB」不是完整答案。</span>"
