            "b": "① 機關現行之<b>資通系統日誌審查</b>活動執行<b>頻率與做法</b>。\n② 機關現行之<b>資料備份</b>執行方式，包含<b>備份頻率、備份儲存媒體及是否進行異地備份</b>等。\n③ 機關現行之<b>系統備援機制</b>或使用其他替代方案。\n④ 機關資通系統<b>多因子鑑別技術</b>適用<b>對象、範圍及實作方式</b>等，如採用之<b>身分驗證因子種類</b>。\n⑤ 機關資通系統<b>委外</b>如何<b>驗證系統安全需求已完成實作</b>。\n⑥ 針對<b>無法修復之資通系統安全漏洞</b>，機關採用之<b>補償與管理作為</b>。\n備註：六題正好對應本單元六大必背——<b>日誌留存 6 個月與定期審查、三種備份方式與異地 30 公里、MTPD／RTO／RPO、多因子鑑別與三類因子、SSDLC 委外階段納入契約、漏洞修復與補償措施</b>。"
