            "b": "<b>定義</b>：是一台<b>專屬的硬體</b>或是<b>架設在一般硬體上的軟體</b>，<b>依照特定的規則允許或限制傳輸的資料通過網路</b>。\n<b>用途 3 項</b>：\n① <b>區隔不同安全等級網段</b>（如<b>外部網路、內部網路及 DMZ</b>）\n② <b>過濾資料封包</b>，避免<b>未經授權存取內部網路資源</b>\n③ 提供<b>稽核與控制存取網路資源</b>\n<span class=\"hl-r\">「DMZ」＝對外服務區，是防火牆劃分的三大區之一，單元 7 網路區域六區還會再考。</span>"
