            "b": "<b>資通安全監控管理機制（Security Operation Center, SOC）</b>：提供<b>資通設備紀錄與資訊服務或應用程式紀錄</b>等<b>資安監控、事件處理、資安威脅預警</b>等服務，<b>適用於 A 級機關及 B 級機關</b>。\n<b>SOC 監控範圍（9 項）</b>：\n① <b>端點偵測及應變機制（EDR）</b>\n② 資通安全防護：<b>防毒軟體</b>\n③ 資通安全防護：<b>網路防火牆</b>\n④ 資通安全防護：<b>電子郵件過濾機制</b>\n⑤ 資通安全防護：<b>入侵偵測及防禦機制（IDS/IPS）</b>\n⑥ 資通安全防護：<b>應用程式防火牆</b>\n⑦ 資通安全防護：<b>進階持續性威脅攻擊防禦措施（APT）</b>\n⑧ <b>目錄服務系統</b>\n⑨ <b>核心資通系統之日誌紀錄及資通設備紀錄</b>\n<b>其他監控範圍</b>：建議可<b>依機關實務需求</b>納入監控。\n<span class=\"hl-r\">易漏的兩項是 <b>⑧ 目錄服務系統</b>與 <b>⑨ 核心資通系統日誌</b>——SOC 不是只收資安設備的告警。</span>"
