            "b": "<b>政府組態基準（Government Configuration Baseline, GCB）</b>：目的在於<b>規範資通訊設備</b>（如<b>個人電腦、伺服器主機及網通設備</b>等）之<b>一致性安全設定</b>（如<b>密碼長度、更新期限</b>等），<b>提升政府機關資通訊設備之資安防護</b>。\n面向 | 內容\n<b>政策要求</b> | <b>從中央部會推動至所屬機關及地方政府</b>\n<b>部署範圍</b> | <b>從終端設備擴及至伺服器及資通安全設備</b>\n<b>強制對象</b> | <b>GCB 導入是 A 級與 B 級「公務機關」必須辦理事項</b>\n<b>兩大效益</b>：① <b>發展一致性安全組態設定</b> ② <b>提升政府機關資通訊設備之資安防護</b>。\n<span class=\"hl-r\">陷阱：GCB <b>只適用公務機關</b>，特定非公務機關（含關鍵基礎設施提供者）<b>不在強制之列</b>。</span>"
