            "b": "<b>定義</b>：是一種資安評估方法，係<b>透過特定的工具或程序，檢查系統或應用程式是否存在「已知的」安全弱點</b>。\n<b>六個目的</b>：\n① <b>評估資安防護能力</b>：了解掃描目標目前的資安保護狀況\n② <b>發現潛在弱點</b>：主動找出可能被利用的安全漏洞\n③ <b>提供改善建議</b>：依據掃描結果提供修補弱點的方法與建議\n④ <b>提升系統安全</b>：協助組織依掃描結果進行修補，強化整體防護成效\n⑤ <b>作為管理依據</b>：掃描結果可作為<b>主機資訊安全管理的參考基準</b>\n⑥ <b>確認弱點已排除</b>：透過後續<b>複掃</b>驗證已發現的弱點是否已成功修補\n<span class=\"hl-r\">關鍵字：弱點掃描找的是「<b>已知</b>」弱點（比對弱點資料庫），這是它與滲透測試（模擬攻擊）最根本的差別。</span>"
