            "b": "<b>定義</b>：是一種資安評估方法，係<b>透過模擬有心人士之攻擊方式，對系統或物聯網設備進行「安全強度」的測試</b>。\n<b>五個目的</b>：\n① <b>評估防護能力</b>：檢測受測目標在<b>遭遇攻擊活動時</b>之資安防護能力與執行成效\n② <b>發現潛在弱點</b>：主動找出可能被利用的安全漏洞\n③ <b>提供改善建議</b>：依據結果提供修補弱點的方法與建議\n④ <b>確認弱點已排除</b>：透過<b>複測</b>確認初測找出之資安漏洞已完成修正\n⑤ <b>精進整體防護</b>：透過報告及改善建議，<b>檢討與精進受測目標之整體資安防護作為</b>\n<span class=\"hl-r\">與弱點掃描的定義對照：<b>弱掃＝檢查「是否存在已知弱點」；滲透＝模擬攻擊測試「安全強度」</b>；滲透測試對象還包含<b>物聯網設備</b>。</span>"
