            "b": "<b>健診目的 3 項</b>：\n① <b>整合各資通安全項目的檢視服務作業</b>，提供機關<b>資通安全改善建議</b>\n② 藉由實施<b>技術面與管理面</b>的相關控制措施，<b>提升機關整體資通安全防護能力</b>\n③ <b>針對已知弱點進行修補</b>，並<b>持續追蹤可能存在的風險</b>\n<b>辦理項目細項（6 項）與頻率</b>：\n辦理項目細項 | A 級 | B 級／C 級 | D 級／E 級\n<b>網路架構檢視</b> | 每年辦理 1 次 | 每 2 年辦理 1 次 | 無要求\n<b>網路惡意活動檢視</b> | 每年辦理 1 次 | 每 2 年辦理 1 次 | 無要求\n<b>使用者端電腦惡意活動檢視</b> | 每年辦理 1 次 | 每 2 年辦理 1 次 | 無要求\n<b>伺服器主機惡意活動檢視</b> | 每年辦理 1 次 | 每 2 年辦理 1 次 | 無要求\n<b>目錄服務系統設定及防火牆連線設定檢視</b> | 每年辦理 1 次 | 每 2 年辦理 1 次 | 無要求\n<b>核心資通系統資料庫安全檢視</b> | 每年辦理 1 次 | 每 2 年辦理 1 次 | 無要求\n<span class=\"hl-r\">數字必背：<b>健診＝A 級每年 1 次、B／C 級每 2 年 1 次、D／E 級無要求</b>（<b>B 與 C 同一格</b>，與安全性檢測的 B、C 分開不同）；項目<b>共 6 項</b>。</span>"
