            "b": "<b>委外定義</b>：將機關之<b>資通服務所有相關活動，部分或全部由「機關外之資通服務提供者」完成</b>。\n資訊委外類別 | 說明\n<b>系統發展類</b> | <b>專注於創建及實施新的資訊系統</b>\n<b>維運管理類</b> | <b>確保現有系統的平穩運行及維護</b>\n<b>顧問訓練類</b> | <b>提供專業知識及培訓，以增強內部能力</b>\n<b>雲端服務類</b> | <b>利用雲端技術實現可擴展性及靈活性</b>\n<span class=\"hl-r\">定義的關鍵字：<b>「部分或全部」</b>——只把一部分工作外包也算委外，一樣受 §10 與施行細則 §7 規範。</span>"
