            "b": "<b>計畫階段重點</b>：<b>評估個案之「委外可行性」與「委外風險」，以確認是否進行委外</b>。\n<b>區分為三個步驟</b>：\n① <b>委外可行性分析</b>\n② <b>委外專案編成</b>\n③ <b>委外資安需求識別</b>\n<span class=\"hl-r\">關鍵觀念：計畫階段的產出是<b>「要不要委外」的決定</b>，不是「找哪一家廠商」（那是招標階段）。</span>"
