            "b": "面向 | 內容\n<b>資訊委外實體與環境安全</b> | 防止機關內資訊因委外而遭<b>未經授權的實體存取、損害及干擾</b>；<b>關鍵或敏感的資訊處理設施宜置放於安全區域</b>，並經由<b>適當之安全屏障與進出控制措施</b>加以保護\n<b>資訊委外管理</b> | 委外相關作業應<b>符合機關安全政策與程序、資通系統防護基準之要求</b>\n<b>資訊委外使用者存取管理</b> | 機關宜有<b>正式程序</b>控制資通系統與服務的<b>存取權限配置作業</b>；程序應<b>從開始登記使用註冊，到最終不再需要存取資通系統與服務「註銷」</b>\n<b>資訊委外資通安全事件管理</b> | ① 機關宜<b>備妥正式的事件通報與提報程序</b>，<b>提供委外廠商配合並施予合宜訓練</b> ② 委外廠商宜<b>認知可能對機關資產安全造成衝擊事件與弱點之通報程序</b>，並要求<b>所有人員儘快向「指定聯絡點」通報任何資安事件與弱點</b>\n<span class=\"hl-r\">最常考的是存取管理的<b>「全生命週期」概念：從註冊到註銷</b>——專案結束卻沒收回帳號是典型缺失。</span>"
