            "h": "⭐⭐ 簡報 3-116｜四個級別與綜評方式（必背）",
            "b": "<b>資通安全事件分級由輕至重分「1」、「2」、「3」、「4」四個級別</b>。評定時，將以<b>資訊或資通系統性質</b>與其 <b>CIA 衝擊性</b>綜評該事件級別。\n資訊或資通系統性質（4 類） | CIA 衝擊性 | 綜評方式\n① <b>（涉及／未涉及 CI）核心業務資訊或資通系統</b>　② <b>非核心業務資訊或資通系統</b>　③ <b>一般公務機密</b>　④ <b>國家機密</b> | <b>機密性、完整性、可用性</b> | <b>以「最高級別」評為該資通安全事件通報等級</b>\n<b>兩個名詞定義（逐字背）</b>：\n名詞 | 定義\n<b>一般公務機密</b>（文書處理手冊第 51 項） | 指本機關持有或保管之資訊，<b>除國家機密外，依法令有保密義務者</b>\n<b>國家機密</b>（國家機密保護法 §2 及 §4） | 指為確保<b>國家安全或利益</b>而有保密之必要，對政府機關持有或保管之資訊，<b>經依本法核定機密等級者</b>（<b>絕對機密、極機密、機密</b>）\n<span class=\"hl-r\">最高頻的一句：<b>三個構面取「最高」者為事件等級</b>（不是取平均、也不是取最低）。</span>"
