            "h": "⭐ 簡報 3-117｜三面向衝擊性的評估架構（本張為概念圖）",
            "b": "資安事件影響等級評定須考量<b>三面向衝擊性</b>：<b>「機密性」衝擊、「完整性」衝擊、「可用性」衝擊</b>——<b>綜合評估後核判影響等級</b>。\n另一軸為<b>資訊或通訊系統性質</b>（由重到輕）：<b>國家機密 → 一般公務機密 → 涉及關鍵基礎設施維運（之核心業務資訊或資通系統）→ 核心業務資訊或資通系統 → 非核心業務資訊或資通系統</b>。\n<b>兩軸交叉</b>：<b>CIA 衝擊由「嚴重」到「輕微」</b>，配上系統性質，即得出<b>該資通安全事件通報等級</b>，並<b>以最高級別為準</b>。\n<span class=\"hl-r\">理解這張圖就掌握了 3-118～3-121 四張表的共同邏輯：<b>「東西多重要」×「被害多嚴重」</b>。</span>"
