            "b": "影響等級 | 說明\n<b>第 1 級（輕微）</b> | <b>非核心</b>資通系統受影響或停頓，<b>於可容忍中斷時間內回復</b>正常運作，造成<b>機關日常作業影響</b>\n<b>第 2 級</b> | <b>非核心</b>資通系統受影響或停頓，<b>無法於可容忍中斷時間內回復</b>，或<b>未涉及 CI 維運之核心</b>資通系統受影響或停頓但<b>可於可容忍中斷時間內回復</b>\n<b>第 3 級</b> | <b>未涉及 CI 維運之核心</b>資通系統受影響或停頓且<b>無法於可容忍中斷時間內回復</b>，或<b>涉及 CI 維運之核心</b>資通系統受影響或停頓但<b>可於可容忍中斷時間內回復</b>\n<b>第 4 級（嚴重）</b> | <b>涉及 CI 維運之核心</b>資通系統受影響或停頓，<b>無法於可容忍中斷時間內回復</b>正常運作\n<b>可容忍中斷時間</b>：政府機關應<b>考量業務性質及影響程度</b>等因素，<b>評定可容許的中斷時間</b>。\n<span class=\"hl-r\">可用性的分級關鍵不是「壞多久」，而是<b>「能不能在可容忍中斷時間內回復」</b>（可／不可）；且<b>可用性沒有「一般公務機密／國家機密」這兩列</b>。</span>"
