            "b": "<b>數位證據（Digital Evidence）</b>：\n① <b>由電腦來儲存或是傳送的資料</b>\n② 該資料<b>可以用來進行後續的偵查</b>\n③ 偵查的目的是用來<b>確認或是否定反駁有關於犯罪的推斷陳述</b>\n④ 該資料<b>在法庭上有具體的用途</b>\n<span class=\"hl-r\">關鍵字：數位證據可以用來<b>「確認」也可以用來「否定反駁」</b>——不是只為了證明有罪。</span>"
