            "h": "⭐⭐ 簡報 3-143｜數位鑑識的定義與兩種用途",
            "b": "<b>數位鑑識（Digital Forensics）</b>：\n① 是<b>鑑識科學的領域之一</b>\n② <b>探討與電腦犯罪相關證物的調查</b>\n③ <b>可運用在法庭上支持或是否定犯罪的推論</b>\n④ 也<b>可運用在一般場合提供資安事件的調查</b>\n<span class=\"hl-r\">兩種用途要一起記：<b>法庭上（支持或否定犯罪推論）＋一般場合（資安事件調查）</b>——不是只有上法院才用得到。</span>"
