            "b": "手法 | 說明\n<b>網路釣魚（Phishing）</b> | 攻擊者<b>偽裝成可信賴的實體</b>（如<b>銀行、政府機關、知名企業或公司內部同事</b>），透過<b>電子郵件或其他電子通訊方式</b>發送虛假訊息\n<b>釣魚簡訊（Smishing）</b> | Phishing 的<b>簡訊變體（SMS ＋ Phishing）</b>；攻擊者透過<b>手機簡訊</b>發送惡意連結或詐騙訊息\n<b>電話詐騙（Vishing）</b> | Phishing 的<b>語音變體（Voice ＋ Phishing）</b>；攻擊者透過<b>電話</b>冒充特定機構（如<b>銀行客服、電信公司、技術支援人員、執法機關</b>）進行詐騙\n<b>即時通訊詐騙（Instant Messaging Scams）</b> | 攻擊者透過<b>即時通訊軟體</b>（如 Line、WhatsApp、Telegram、Facebook Messenger）進行的詐騙\n<span class=\"hl-r\">字源記法：<b>Smishing ＝ SMS＋Phishing（簡訊）</b>、<b>Vishing ＝ Voice＋Phishing（電話）</b>。</span>"
