            "b": "<b>總原則</b>：<b>隨時提高警覺，在沒有適當的認證情況下，不應輕信他人；只要出現社交工程攻擊警訊，都應保持小心求證的戒心</b>。\n<b>五不</b>：\n① <b>不未經確認即提供資料</b>\n② <b>不開啟來路不明的電子郵件及附加檔案</b>\n③ <b>不連結及登入未經確認的網站</b>\n④ <b>不下載非法軟體及檔案</b>\n⑤ <b>避免在公共場所使用免費 WiFi 熱點</b>\n<b>另兩項</b>：<b>任何資訊釋出時都要確認要求者的身分及對方經過授權</b>；<b>遇到疑似攻擊事件時應向有關單位通報</b>。\n<span class=\"hl-r\">易漏的是第 ⑤ 項<b>公共免費 WiFi</b>，以及最後一句<b>「遇到疑似攻擊要通報」</b>（不是自己刪信了事）。</span>"
